// Runs the Showdown Flavored Markdown spec suite (specs/showdown.md, extracted to
// showdown.testsuite.json by `npm run extract:spec`) against the `vanilla` flavor.
//
// This is the executable contract for the default converter. Unlike the single-converter
// original/gfm suites, each case is run with its own converter built from the options the
// example declares in its fence annotation (mirroring testsuite.features.js), so an example
// tagged `options:tables` runs with tables on and every other example runs with pure
// defaults.

// jshint ignore: start
let bootstrap = require('./makehtml.bootstrap.js'),
    showdown = bootstrap.showdown,
    assertion = bootstrap.assertion,
    testsuite = bootstrap.getJsonTestSuite('test/functional/makehtml/cases/showdown.testsuite.json');

describe('makeHtml() showdown (vanilla) testsuite', function () {
  'use strict';

  for (let section in testsuite) {
    if (Object.prototype.hasOwnProperty.call(testsuite, section)) {
      describe(section, function () {
        for (let i = 0; i < testsuite[section].length; ++i) {
          let testCase = testsuite[section][i];
          let name = testCase.name;
          let number = testCase.number;
          // each case carries the converter options it needs in the fixture (vanilla defaults
          // otherwise)
          let converter = new showdown.Converter(testCase.options);
          it(number + ': ' + name, assertion(testCase, converter, true));
        }
      });
    }
  }
});

test/unit/showdown.Converter.js.source:
/**
 * Created by Estevao on 31-05-2015.
 */


describe('showdown.Converter', function () {
  'use strict';

  describe('option methods', function () {
    let converter = new showdown.Converter();

    it('setOption() should set option foo=baz', function () {
      converter.setOption('foo', 'baz');
    });

    it('getOption() should get option foo to equal baz', function () {
      expect(converter.getOption('foo')).toBe('baz');
    });

    it('getOptions() should contain foo=baz', function () {
      let options = converter.getOptions();
      expect(Object.prototype.hasOwnProperty.call(options, 'foo')).toBe(true);
      expect(options.foo).toBe('baz');
    });
  });

  describe('metadata methods', function () {
    let converter = new showdown.Converter();

    it('_setMetadataPair() should set foo to bar', function () {
      converter._setMetadataPair('foo', 'bar');
      expect(converter.getMetadata()).toEqual({foo: 'bar'});
    });

    it('_setMetadata should set metadata to {baz: bazinga}', function () {
      converter._setMetadataRaw('{baz: bazinga}');
      expect(converter.getMetadata(true)).toEqual('{baz: bazinga}');
    });
  });

  describe('converter.setFlavor()', function () {

    /**
     * Test setFlavor('gfm')
     */
    describe('gfm', function () {
      let converter = new showdown.Converter(),
          ghOpts = showdown.getFlavorOptions('gfm');

      converter.setFlavor('gfm');

      for (let opt in ghOpts) {
        if (Object.prototype.hasOwnProperty.call(ghOpts, opt)) {
          check(opt, ghOpts[opt]);
        }
      }
      function check (key, val) {
        it('should set ' + key + ' to ' + val, function () {
          expect(converter.getOption(key)).toBe(val);
        });
      }
    });
  });

  describe('getFlavor method', function () {

    // reset showdown
    showdown.setFlavor('vanilla');

    describe('flavor', function () {
      it('should be vanilla by default', function () {
        let converter = new showdown.Converter();
        expect(converter.getFlavor()).toBe('vanilla');
      });

      it('should be changed if global option is changed', function () {
        showdown.setFlavor('gfm');
        let converter = new showdown.Converter();
        expect(converter.getFlavor()).toBe('gfm');
        showdown.setFlavor('vanilla');
      });

      it('should not be changed if converter is initialized before global change', function () {
        let converter = new showdown.Converter();
        showdown.setFlavor('gfm');
        expect(converter.getFlavor()).toBe('vanilla');
        showdown.setFlavor('vanilla');
      });
    });
  });

  describe('extension methods', function () {
    // `lang`/`output` extensions are sugar over the event system, so they are asserted by
    // the effect they have on the converted output rather than by introspection.
    let extObjMock = {
          type: 'lang',
          regex: /markdown/g,
          replace: 'showdown'
        },
        extObjFunc = function () {
          return extObjMock;
        };

    it('addExtension() should add an extension Object', function () {
      let converter = new showdown.Converter();
      converter.addExtension(extObjMock);
      expect(converter.makeHtml('markdown')).toMatch(/showdown/);
    });

    it('addExtension() should unwrap an extension wrapped in a function', function () {
      let converter = new showdown.Converter();

      converter.addExtension(extObjFunc);
      expect(converter.makeHtml('markdown')).toMatch(/showdown/);
    });

    it('useExtension() should use a previous registered extension in showdown', function () {
      showdown.extension('foo', extObjMock);
      let converter = new showdown.Converter();

      converter.useExtension('foo');
      expect(converter.makeHtml('markdown')).toMatch(/showdown/);
      showdown.resetExtensions();
    });

    it('should warn at most once per process for a deprecated extension type', function () {
      // robust to global ordering: an earlier suite may already have tripped the per-process
      // flag, so we assert "at most once". The old per-load behavior would have warned twice.
      let orig = console.warn,
          count = 0;
      console.warn = function () { count++; };
      try {
        new showdown.Converter({extensions: [{type: 'lang', regex: /a/g, replace: 'b'}]});
        new showdown.Converter({extensions: [{type: 'lang', regex: /a/g, replace: 'b'}]});
      } finally {
        console.warn = orig;
      }
      expect(count).toBeLessThanOrEqual(1);
    });
  });

  describe('events', function () {
    it('should fire a listener on a real event and let it modify the output', function () {
      let fired = false,
          converter = new showdown.Converter();
      converter.listen('makehtml.heading.atx.onCapture', function (event) {
        fired = true;
        event.attributes.class = 'x';
        return event;
      });
      let html = converter.makeHtml('# foo');
      expect(fired).toBe(true);
      expect(html).toMatch(/class="x"/);
    });

    it('should NOT fire the removed .before/.after special events', function () {
      let fired = false;
      new showdown.Converter()
        .listen('makehtml.heading.before', function (e) { fired = true; return e; })
        .makeHtml('# foo');
      expect(fired).toBe(false);
    });
  });
});

test/unit/showdown.Converter.makeHtml.js.source:
/**
 * Created by Tivie on 15-01-2015.
 *
 * makeHtml() coverage that a fixture cannot express. Per-option conversion behavior lives in
 * test/functional/makehtml/cases/features.testsuite.json (and the spec suites); what remains
 * here asserts invocation counts, thrown errors, post-conversion accessor state, and the one
 * option whose effect the functional harness normalizes away (see omitExtraWLInCodeBlocks).
 */


describe('showdown.Converter', function () {
  'use strict';

  describe('Converter.options extensions', function () {
    let runCount;
    showdown.extension('testext', function () {
      return [{
        type: 'output',
        filter: function (text) {
          runCount = runCount + 1;
          return text;
        }
      }];
    });

    let converter = new showdown.Converter({extensions: ['testext']});

    it('output extensions should run once', function () {
      runCount = 0;
      converter.makeHtml('# testext');
      expect(runCount).toBe(1);
    });
  });

  describe('makeHtml() with option omitExtraWLInCodeBlocks', function () {
    // Deliberately NOT a fixture: the option's only effect is the trailing newline before
    // `</code>`, and the functional harness prettifies both sides with diffable-html, which
    // re-indents `<pre><code>` content and normalizes that newline away. A fixture would
    // therefore pass identically with the option on or off.
    let converter = new showdown.Converter({omitExtraWLInCodeBlocks: true}),
        text = 'var foo = bar;',
        html = converter.makeHtml('    ' + text);
    it('should omit extra line after code tag', function () {
      let expectedHtml = '<pre><code>' + text + '</code></pre>';
      expect(html).toBe(expectedHtml);
    });
  });

  describe('makeHtml() with option headerIds', function () {
    it('should throw a TypeError for an invalid headerIds value', function () {
      expect(function () {
        new showdown.Converter({ headerIds: 3 });
      }).toThrow();
    });
  });

  describe('makeHtml() with option metadata', function () {
    let converter = new showdown.Converter(),
        text1 =
          '---SIMPLE\n' +
          'foo: bar\n' +
          'baz: bazinga\n' +
          '---\n',
        text2 =
          '---TIVIE\n' +
          'a: b\n' +
          'c: 123\n' +
          '---\n';

    it('should correctly set metadata', function () {
      converter.setOption('metadata', true);

      let expectedHtml = '',
          expectedObj = {foo: 'bar', baz: 'bazinga'},
          expectedRaw = 'foo: bar\nbaz: bazinga',
          expectedFormat = 'SIMPLE';
      expect(converter.makeHtml(text1)).toBe(expectedHtml);
      expect(converter.getMetadata()).toEqual(expectedObj);
      expect(converter.getMetadata(true)).toBe(expectedRaw);
      expect(converter.getMetadataFormat()).toBe(expectedFormat);
    });

    it('consecutive calls should reset metadata', function () {
      converter.makeHtml(text2);
      let expectedObj = {a: 'b', c: '123'},
          expectedRaw = 'a: b\nc: 123',
          expectedFormat = 'TIVIE';
      expect(converter.getMetadata()).toEqual(expectedObj);
      expect(converter.getMetadata(true)).toBe(expectedRaw);
      expect(converter.getMetadataFormat()).toBe(expectedFormat);
    });
  });
});

